import{_ as a,o as n,c as e,ai as l}from"./chunks/framework.Ba-VnP44.js";const h=JSON.parse('{"title":"04 功能开发","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/02-lifecycle/development.md","filePath":"ai/productivity/dev-spec/02-lifecycle/development.md"}'),i={name:"ai/productivity/dev-spec/02-lifecycle/development.md"};function p(r,s,t,d,c,b){return n(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="_04-功能开发" tabindex="-1">04 功能开发 <a class="header-anchor" href="#_04-功能开发" aria-label="Permalink to “04 功能开发”">​</a></h1><blockquote><p>第二层 · 开发生命周期。解决「让 AI 连续编码而不是每步都等确认」——用计划、状态、检查点支撑连续执行，人只在关键决策点拍板。</p></blockquote><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to “什么时候用”">​</a></h2><p>方案已定、子任务已拆解，进入实际编码。L1 简单任务可直接做；L2/L3 按连续执行机制推进。</p><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to “操作步骤”">​</a></h2><h3 id="连续执行靠三样东西" tabindex="-1">连续执行靠三样东西 <a class="header-anchor" href="#连续执行靠三样东西" aria-label="Permalink to “连续执行靠三样东西”">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>内容</th><th>什么时候读</th></tr></thead><tbody><tr><td><code>TASK-PLAN.md</code></td><td>子任务、依赖、完成标准、不做项、停止条件</td><td>每轮开始</td></tr><tr><td><code>PROGRESS.md</code></td><td>每轮做了什么、命令输出、失败记录、下一步</td><td>每轮开始、恢复会话时</td></tr><tr><td><code>DECISIONS.md</code>（可选）</td><td>执行中的小决定及依据</td><td>有争议时回查</td></tr></tbody></table><p>状态用五种：<code>pending → in_progress → done / blocked / skipped</code>。<code>done</code> 要有证据；<code>blocked</code> 要写明原因和需要谁提供什么。</p><h3 id="每轮固定动作" tabindex="-1">每轮固定动作 <a class="header-anchor" href="#每轮固定动作" aria-label="Permalink to “每轮固定动作”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 读状态    读 TASK-PLAN.md 和 PROGRESS.md 末尾</span></span>
<span class="line"><span>2. 选任务    按依赖顺序选下一个 pending，标 in_progress</span></span>
<span class="line"><span>3. 执行      只做这一个子任务，遵守范围与不做项</span></span>
<span class="line"><span>4. 验证      跑该任务完成标准对应的命令，记录输出</span></span>
<span class="line"><span>5. 记录      写 PROGRESS.md，更新状态</span></span>
<span class="line"><span>6. 提交      验证通过再提交，进入下一轮</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="人必须在场的情况" tabindex="-1">人必须在场的情况 <a class="header-anchor" href="#人必须在场的情况" aria-label="Permalink to “人必须在场的情况”">​</a></h3><ul><li>业务规则有多种合理解释。</li><li>涉及权限、支付、资金、库存，或要删数据、改生产配置、执行不可逆操作。</li><li>要改接口签名、新增核心依赖、升级框架。</li><li>要动禁改区或没有测试覆盖的老代码。</li><li>到达方案里约定的检查点。</li></ul><p>确认时只需回答三件事：选哪个方案、加哪些边界、哪些风险不接受。不替 AI 写代码。</p><h3 id="立即停手的信号" tabindex="-1">立即停手的信号 <a class="header-anchor" href="#立即停手的信号" aria-label="Permalink to “立即停手的信号”">​</a></h3><p>AI 说「顺手把……也改了」、开始改依赖文件或公共模块、同一问题出现多种解释、重复问已回答的问题、完成标准被悄悄放宽。</p><p><strong>失败先分类，不要一律重试</strong>：代码错误可重试有限轮次；环境问题标 blocked；认知问题（改 A 坏 B）停手回分析；需求冲突交人确认。详见 <a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/bugfix.html">06 逻辑与 BUG 修复</a>。</p><h3 id="中断恢复" tabindex="-1">中断恢复 <a class="header-anchor" href="#中断恢复" aria-label="Permalink to “中断恢复”">​</a></h3><p>让 AI 读 <code>PROGRESS.md</code> 末尾状态接上，不要重做已完成的子任务，不要删已有改动。</p><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>启动连续执行</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>接下来的任务按连续执行方式推进。本轮先不要写代码，只确认执行规则。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>已提供：TASK-PLAN.md、PROGRESS.md、全局 Rules、本次 Spec（填路径）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请确认以下规则，然后从第一个子任务开始：</span></span>
<span class="line"><span>1. 每轮只执行一个 pending 子任务，按依赖顺序，不跳。</span></span>
<span class="line"><span>2. 每轮先读计划和进度末尾的状态，严格遵守不做项和修改范围，超出范围先停。</span></span>
<span class="line"><span>3. 子任务完成后执行完成标准对应的命令，原样记录输出。</span></span>
<span class="line"><span>4. 每轮结束写 PROGRESS.md、更新状态再提交。</span></span>
<span class="line"><span>5. 验证失败先说明本轮假设为什么错了，同一错误建议最多试几轮，仍失败标 blocked 并说明原因。</span></span>
<span class="line"><span>6. 到检查点停下来等我确认，不要自行通过。</span></span>
<span class="line"><span>7. 不要自己宣布整个任务完成——最终验收由人对照清单判定。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果规则可行，从 T1 开始执行第一轮。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div></details><details><summary><strong>中断恢复</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我需要恢复一个中断的开发任务。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请先读取：&lt;TASK-PLAN.md 路径&gt;、&lt;PROGRESS.md 路径&gt;、当前 git status 和最近几条 git log。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>然后只做四件事：</span></span>
<span class="line"><span>1. 复述当前状态：已完成哪些、进行中是哪个、下一轮是谁。</span></span>
<span class="line"><span>2. 核对文件状态与 PROGRESS.md 是否一致，不一致的列出来，不自行猜原因。</span></span>
<span class="line"><span>3. 指出上一轮遗留的问题和未解决的阻塞。</span></span>
<span class="line"><span>4. 等我确认后从下一轮继续执行。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要重做已完成任务，不要删除已有改动。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 每轮只做一个子任务，完成标准达成且有命令输出证据。</li><li>[ ] 改动文件都在允许范围，不做项未被触碰。</li><li>[ ] 每轮写 PROGRESS.md 并提交，状态与实际一致。</li><li>[ ] 失败先分类，没有在同一错误上无限重试。</li><li>[ ] 检查点停下来等确认，AI 没有自行宣布整体完成。</li></ul><p>开发中发现问题进入 <a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/review.html">05 功能审查与完善</a> 或 <a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/bugfix.html">06 逻辑与 BUG 修复</a>；每轮改动都要按第三层 <a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/git-version.html">Git 与版本管理</a> 检查。</p>`,24)])])}const m=a(i,[["render",p]]);export{h as __pageData,m as default};
